\begin{subequations}\label{Eq:c_Bogo_general}
\begin{gather}
c_{d, \mathrm{B}}^2 = \frac{1}{2m} \left[ g (n_1 + n_2) - \sqrt{g^2(n_1 - n_2)^2 + 4 g_{12}^2 n_1 n_2} \right] \, , \\
